sp_header_footer.client_script:
api.controller = function ($rootScope, $scope, snRecordWatcher, spUtil, $location, $uibModal, cabrillo, $timeout, $window, i18n) {

	$scope.logoText = i18n.format(i18n.getMessage('Go to {0} Homepage'), $scope.portal.title);
	$scope.collapse = function() {
		$rootScope.$emit('sp-navbar-collapse');
	}

	$scope.avatarProfile = {
		userID: $scope.user.sys_id,
		name: $scope.user.name,
		initials: $window.NOW.user_initials
	};

	if ($window.NOW.user_avatar) {
		$scope.avatarProfile.userImage = $window.NOW.user_avatar;
	}

	if (cabrillo.isNative()) {
		if ($window.innerWidth < 767) {
			$scope.isViewNative = true;
		} else {
			$scope.isViewNativeTablet = true;
		}
	}


	$scope.openPopUp = function() {
		var url = "$chat_support.do?queueID=" + $scope.data.connect_support_queue_id;
		var popup = window.open (url, "popup", "width=900, height=600");
	};

	$scope.openLogin = function () {
		$scope.modalInstance = $uibModal.open({
			templateUrl: 'modalLogin',
			scope: $scope
		});

		var pageRoot = angular.element('.sp-page-root');
		$scope.modalInstance.rendered.then(function() {
			var $uibModalStack = $injector.get('$uibModalStack');
			var modalObj = $uibModalStack.getTop();
			var modal = modalObj.value.modalDomEl;

			modal.attr('aria-label', modal.find('.panel-title').html());
			modal.attr('aria-modal', 'true');
			pageRoot.attr('aria-hidden', 'true');
		});

		$scope.modalInstance.closed.then(function() {
			pageRoot.attr('aria-hidden', 'false');
		});
	};

	var mdScreenSize = isMDScreenSize();
	$scope.showSMAvatar = isMDScreenSize();
	$scope.showAvatar = !isMDScreenSize();

	$scope.isAgentChatConfigured = g_has_agent_chat_config;

	var nav = document.getElementById('responsiveNav');

	function isMDScreenSize() {
		if (nav)
			return nav.classList.contains('responsive-tablet');
		else return false;
	}

	function updateResponsiveClasses(width) {
		if (width <= 992) {
			nav.classList.add('responsive-tablet');
			nav.classList.remove('responsive-desktop');
		} else {
			nav.classList.add('responsive-desktop');
			nav.classList.remove('responsive-tablet');
		}
		if(mdScreenSize !== isMDScreenSize() && (!$scope.showSMAvatar || !$scope.showAvatar)){
			$scope.showSMAvatar = true;
			$scope.showAvatar = true;
		}
	}

	var observer = new ResizeObserver(function(entries) {
		if (entries && entries[0]) {
			updateResponsiveClasses(entries[0].contentRect.width);
		}
	});
	observer.observe(nav);

	$rootScope.$on('sp.avatar_changed', function(evt, obj) {
		$scope.userID = "";
		$scope.newAvatarId = obj.newAvatarId;
		$timeout(function(){
			$scope.userID = $scope.user.sys_id;
			$("#profile-dropdown .sub-avatar").css("background-image", 'url("' + $scope.newAvatarId + '.iix?t=small")');
		});
	});

	$scope.isHomepage = function() {
		if (!$scope.page.id)
			return true;

		if ($scope.page.id == $scope.portal.homepage_dv)
			return true;

		return false;
	};

}

sp_header_footer.css:
// ── Base navbar ──────────────────────────────────────────
.navbar {
  transition: 250ms opacity ease-in-out;
  border: 0;
  border-bottom: $sp-navbar-bottom-width solid $sp-navbar-divider-color;
  min-height: 61px;
}

.navbar-fade { opacity: 0.4; }

.navbar-inverse .navbar-toggle {
  border-color: $sp-navbar-toggle-border-color;
}

header[role="banner"],
.nav > li > a {
  max-height: 61px;
}

.nav > li > a span.fa { margin-left: 0.2rem; }

// ── Brand / Logo ─────────────────────────────────────────
.navbar-brand {
  max-height: 61px;
  padding: 0 0 0.5rem 0;
  display: flex;
  align-items: center;
}

.navbar-brand img,
.navbar-brand span {
  margin: $sp-logo-margin-y $sp-logo-margin-x;
  display: block;
  max-height: $sp-logo-max-height;
  max-width: $sp-logo-max-width;
  position: relative;
  top: 50%;
  transform: translateY(-50%);
  overflow: hidden;
}

// GateNow custom brand
.gn-brand {
  display: flex !important;
  align-items: center;
  gap: 10px;
  padding: 0 16px !important;
  text-decoration: none !important;
}

.gn-logo-icon {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}

.gn-brand-text {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.3px;
  line-height: 1;
}

.gn-brand-gate { color: #ffffff; }
.gn-brand-now  { color: rgba(255,255,255,0.65); }

// ── Hamburger ─────────────────────────────────────────────
.gn-hamburger {
  .icon-bar {
    background-color: #ffffff !important;
    height: 2px;
    border-radius: 2px;
  }
}

// ── Login link ────────────────────────────────────────────
.gn-login-link {
  display: flex !important;
  align-items: center;
  gap: 7px;
  padding: 0 14px !important;
  height: 61px;
  color: rgba(255,255,255,0.85) !important;
  font-size: 13.5px;
  font-weight: 500;
  transition: color 0.15s ease;

  &:hover {
    color: #ffffff !important;
    background: transparent !important;
  }
}

.gn-login-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

// ── Avatar button ─────────────────────────────────────────
.gn-avatar-dropdown > a.gn-avatar-btn,
.gn-avatar-btn {
  display: flex !important;
  align-items: center;
  gap: 8px;
  height: 61px;
  padding: 0 12px !important;
  color: #ffffff !important;
  background: transparent !important;
  border: none;
  text-decoration: none !important;
  cursor: pointer;
  transition: background 0.15s ease;

  &:hover,
  &:focus {
    background: rgba(255,255,255,0.08) !important;
    color: #ffffff !important;
  }
}

.gn-user-name {
  font-size: 13.5px;
  font-weight: 500;
  max-width: 130px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gn-chevron {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  opacity: 0.8;
  transition: transform 0.2s ease;
}

.gn-avatar-dropdown.open .gn-chevron {
  transform: rotate(180deg);
}

// ── Dropdown menu ─────────────────────────────────────────
.gn-dropdown-menu {
  border: none !important;
  border-radius: 12px !important;
  box-shadow: 0 8px 32px rgba(0,0,0,0.14) !important;
  padding: 6px !important;
  min-width: 200px !important;
  right: 0 !important;
  left: auto !important;
  margin-top: 4px !important;
}

// User info header inside dropdown
.gn-dropdown-header {
  padding: 10px 14px 8px !important;
  display: flex;
  flex-direction: column;
  gap: 2px;
  pointer-events: none;
}

.gn-dropdown-name {
  font-size: 13.5px;
  font-weight: 600;
  color: #1D1D2E;
  display: block;
}

.gn-dropdown-role {
  font-size: 11.5px;
  color: #7C7C8E;
  display: block;
}

// Divider
.gn-dropdown-divider {
  height: 1px !important;
  background: #F0EFF8 !important;
  margin: 4px 8px !important;
  padding: 0 !important;
}

// Dropdown items
.gn-dropdown-item {
  display: flex !important;
  align-items: center;
  gap: 9px;
  padding: 9px 14px !important;
  border-radius: 8px !important;
  font-size: 13.5px !important;
  color: #1D1D2E !important;
  transition: background 0.15s ease !important;

  svg { flex-shrink: 0; }

  &:hover,
  &:focus {
    background: #EEEDFB !important;
    color: #5443AD !important;
    text-decoration: none !important;
  }
}

// Logout item
.gn-dropdown-logout {
  color: #EF4444 !important;

  &:hover,
  &:focus {
    background: #FEE2E2 !important;
    color: #DC2626 !important;
  }
}

// ── Mobile nav extras ─────────────────────────────────────
.gn-nav-link {
  display: flex !important;
  align-items: center;
  gap: 8px;
  padding: 10px 16px !important;
  color: rgba(255,255,255,0.85) !important;
  font-size: 13.5px;
  font-weight: 500;

  &:hover {
    color: #ffffff !important;
    background: rgba(255,255,255,0.08) !important;
  }
}

.gn-nav-logout { color: rgba(255,255,255,0.8) !important; }

// ── Responsive helpers (keep stock behavior) ──────────────
.navbar-right {
  padding-right: 0;
  padding-left: 7px;
}

.navbar-nav { margin: 0; }

nav {
  margin-bottom: 0;
  border-radius: 0;

  .toggle-dropdown { height: 61px; }
}

// Desktop flex fix (Safari)
.responsive-desktop {
  .navbar-right {
    display: flex !important;
    height: auto !important;
    align-items: center;
  }
}

// Tablet/mobile overrides
.responsive-tablet {
  .nav > li > a {
    padding-right: 0.5rem;
    padding-left: 0.5rem;
  }

  .navbar-brand img,
  .navbar-brand span {
    max-width: $sp-logo-mobile-max-width;
  }

  .navbar-toggle    { display: block; }
  .navbar-header    { float: none; }
  .navbar-left,
  .navbar-right     { float: none !important; }
  .navbar-nav       { float: none !important; }
  .navbar-nav > li  { float: none; }
  .navbar-nav > li > a {
    padding-top: 1rem;
    padding-bottom: 1rem;
  }
}

// Breadcrumb
.breadcrumb-container { background-color: $panel-bg; }

// Native mobile app
.navbar-inverse.is-native { background-color: #405060; }

// High contrast mode
@media screen and (-ms-high-contrast: active), (forced-colors: active) {
  .navbar-brand,
  .navbar-nav > li > a,
  .skip-link,
  .btn.btn-primary,
  .btn.btn-danger,
  .navbar-inverse .navbar-toggle {
    &:focus { outline-offset: -4px !important; }
  }
}

// Scrollable dropdown
.scrollable-dropdown {
  max-height: 80vh;
  overflow: auto;
  height: auto;
}

.is-native .scrollable-dropdown {
  max-height: 100vh;
  overflow: scroll;
}

sp_header_footer.link:
function app (scope, element) {
	var prevFocusIndex = -1;// This is used for prev focus of nav-bar(avatar) drop down items when its visible.
	var KEY = {
		TAB : 9,
		ENTER : 13,
		ESC : 27,
		SPACE_BAR : 32,
		LEFT : 37,
		UP : 38,
		RIGHT : 39,
		DOWN : 40
	}

	function isMDScreenSize() {
		return window.matchMedia('(max-width: 992px)').matches;
	}

	var navbarContainer = $('#sp-nav-bar');
	navbarContainer.on('shown.bs.collapse', function () {
		$('a:visible', navbarContainer).first().focus();
	});

	$(document).keyup(function(event) {
		var mdScreenSize = isMDScreenSize();
		if (event.which == KEY.TAB || event.which == KEY.LEFT || event.which == KEY.RIGHT) { //tab key handler + arrow keys
			if (!mdScreenSize && $(event.target).parents(".dropdown-menu").length == 0) { //if we are NOT inside a dropdown...
				//close the dropdowns
				$(".dropdown.open", $(element)).removeClass("open");
				$("[data-toggle='dropdown']", $(element)).attr("aria-expanded", "false");
				prevFocusIndex = -1;
			}
		} else if(event.which == KEY.UP || event.which == KEY.DOWN) {
			var parent = $(event.target).parents('.dropdown-menu');

			// To support custom drop downs like cart and wish list.
			if (parent.hasClass('custom-drop-down')) return;

			if (parent.length) {
				var items = $(parent).find('li a, li button');
				if (!items.length)
					return;

				var index = items.index(items.filter(':focus'));
				if(index == -1) return;

				if (prevFocusIndex == index) {
					if (index == 0)
						index = items.length - 1;
					else if (index == items.length - 1)
						index = 0;

						items[index].focus();
				} else if (event.which == KEY.UP && index == 0 && prevFocusIndex == -1) { // to handle newly opened dropdown on keyup
					index = items.length - 1;
					items[index].focus();
				}
				prevFocusIndex = index;

			} else {
				// Upon down/up arrow key event from the menu target element,
        // focus the first/last menu item to be consistent with click behavior and conform to standard menubar pattern below
				// https://www.w3.org/TR/wai-aria-practices/examples/menubar/menubar-1/menubar-1.html
				if ($(event.target).is('[data-toggle="dropdown"]')) {
					var parent = $(event.target).parent().find('.dropdown-menu');

					// To support custom drop downs like cart and wish list.
					if (parent.hasClass('custom-drop-down')) return;

					var items = $(parent).find('li a, li button');
					if (!items.length) return;

					var index = -1;
					if(event.which == KEY.DOWN) //down
						index = 0;
					else if(event.which == KEY.UP) //up
						index = items.length > 0 ? items.length-1 : 0;

					items[index].focus();
					prevFocusIndex = index;

				}		
			}
		}
		// on esc/close of the menu, reset the index
		if(event.which == KEY.ESC) {
			prevFocusIndex = -1;
			if (mdScreenSize && $('.navbar-right').attr("aria-expanded")) {
				closeMobileMenu();

				if ($(event.target).parents(".navbar-right").length > 0)
					$('.navbar-toggle').focus();
			}
		}

		if (event.which == KEY.ENTER || event.which == KEY.SPACE_BAR)
			$(event.target).parent(".dropdown.open").find("ul.dropdown-menu li:first-child a").focus();
	});

	$(element).on('click.nav','.navbar-collapse.in',function(e) {
		var target = $(e.target);
		if (target.is('a')) {
			if (target.hasClass('sp-menu-has-items'))
				return; // menu item has a submenu, so just toggle it

			// collapse mobile nav if clicked an anchor
			$(this).removeClass('in').addClass('collapse');
			return;
		}

		if (target.parent().hasClass("toggle-dropdown")) {
			// collapse mobile nav if parent has toggle-dropdown class
			$(this).removeClass('in').addClass('collapse');
			return;
		}

		// if neither target nor parent is an anchor, do nothing
		if (!target.parent().is('a'))
			return;

		// collapse mobile nav if target is part of a submenu
		if (target.parents("ul.dropdown-menu").length > 0)
			$(this).removeClass('in').addClass('collapse');
	});

	// clicking outside the mobile menu should close the mobile menu
	$(document).on('click', function(e) {
		var target = $(e.target);
		if (target.parents('.navbar-right').length == 0) {
			closeMobileMenu();
		}
	});

	// Close the mobile menu when focus goes out of the menu
	$('.navbar-right').on('keydown', 'a', function(event) {
		if (($(this).is($('.navbar-right a').last()) && event.which == KEY.TAB && !event.shiftKey) || ($(this).is($('.navbar-right a').first()) && event.which == KEY.TAB && event.shiftKey)) {
			closeMobileMenu();
			setTimeout(function () {
				window.scrollBy(0,-200);
			});
		}
	});

	function closeMobileMenu() {
		$('.navbar-right').collapse('hide');
	}
}

sp_header_footer.script:
(function() {

  data.connect_support_queue_id = $sp.getValue('sp_chat_queue');
  data.login_page               = $sp.getValue('login_page');
  data.profileBtnMsg            = gs.getMessage("User options");
  data.toggleMsg                = gs.getMessage("Toggle navigation");

  // Build logout URL → redirects back to portal login page after session clear
  try {
    var portalGr     = $sp.getPortalRecord();
    var urlSuffix    = portalGr.getValue('url_suffix');   // "applicant"
    var loginPageVal = $sp.getValue('login_page');         // "login"
    data.logoutUrl   = '/logout.do?sysparm_redirect=/'
                       + urlSuffix + '%3Fid%3D' + loginPageVal;
  } catch(e) {
    data.logoutUrl = '/logout.do?sysparm_redirect=/applicant%3Fid%3Dlogin';
    gs.logError('GateNow logoutUrl build failed: ' + e.message, 'gatenow-header');
  }

  // Profile link
  data.link = '?id=user_profile&sys_id=' + gs.getUserID();

  // Menu widget
  try {
    var menu  = $sp.getValue("sp_rectangle_menu");
    data.menu = $sp.getWidgetFromInstance(menu);
  } catch(e) {
    data.menu = null;
  }

  // Language selector
  try {
    data.langSelector = gs.isPluginActivated('com.glide.i18n')
      ? $sp.getWidget('sp-lang-selector') : "";
  } catch(e) {
    data.langSelector = "";
  }

  // Parse menu items
  if (data.menu && data.menu.data) {
    data.menu.data.replace = true;
    data.hasLogin          = false;
    data.hasMenuItems      = false;
    try {
      if (data.menu.data.menu && data.menu.data.menu.items) {
        data.hasMenuItems = data.menu.data.menu.items.length > 0;
        for (var i in data.menu.data.menu.items) {
          var item = data.menu.data.menu.items[i];
          if (item.type == 'page' && item.sp_page == data.login_page)
            data.hasLogin = true;
        }
      }
    } catch(e) {}
  }

  // Login modal
  try {
    data.loginWidget = $sp.getWidgetFromInstance('login-modal');
  } catch(e) {
    data.loginWidget = null;
  }

})();
